"""
bulwarkos_wifi.protocol — shared wire protocol constants and helpers.

The wire protocol is newline-delimited JSON over the virtio-serial port.
Both sides (proxy in sys-net, daemon on host) use this module.

Commands (host → sys-net):
    {"id": N, "cmd": "ping"}
    {"id": N, "cmd": "scan"}
    {"id": N, "cmd": "list_networks"}
    {"id": N, "cmd": "connect",    "ssid": "...", "passphrase": "..."}
    {"id": N, "cmd": "disconnect"}
    {"id": N, "cmd": "status"}
    {"id": N, "cmd": "forget",     "ssid": "..."}

Responses (sys-net → host):
    {"id": N, "ok": true/false, ...payload...}

Events (sys-net → host, unsolicited):
    {"event": "connected",     "ssid": "..."}
    {"event": "disconnected"}
    {"event": "state_changed", "state": "..."}
"""

# Commands
CMD_PING         = "ping"
CMD_SCAN         = "scan"
CMD_LIST         = "list_networks"
CMD_CONNECT      = "connect"
CMD_DISCONNECT   = "disconnect"
CMD_STATUS       = "status"
CMD_FORGET       = "forget"

# Events emitted by the proxy
EVENT_CONNECTED     = "connected"
EVENT_DISCONNECTED  = "disconnected"
EVENT_STATE_CHANGED = "state_changed"

# iwd station states
STATE_CONNECTED    = "connected"
STATE_CONNECTING   = "connecting"
STATE_DISCONNECTED = "disconnected"
STATE_UNAVAILABLE  = "unavailable"
STATE_UNKNOWN      = "unknown"

# NetworkManager device state constants (used by NM compatibility shim)
NM_DEVICE_STATE_UNAVAILABLE  = 20
NM_DEVICE_STATE_DISCONNECTED = 30
NM_DEVICE_STATE_ACTIVATED    = 100
NM_CONNECTIVITY_FULL         = 4
NM_CONNECTIVITY_NONE         = 1
